"""Rotation Count of a Rotated Sorted Array — index of the minimum.

Time: O(log n)   Space: O(1)
"""
from typing import List


class Solution:
    def countRotations(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:
                lo = mid + 1
            else:
                hi = mid
        return lo
